<?phprequire_once('common_api_header.php');require_once('../admin/controllers/common_controllers.php');$data_raw = file_get_contents('php://input');$data = json_decode($data_raw,true);setTimeZone();$response = array();function getAssets($conn,$BranchID){	$table_name = "branch_assets";	$where = " where BranchID = $BranchID";	$response = _getTableRecords($conn, $table_name, $where);	return $response;}if(isset($data['BranchID'])){	$BranchID = $data['BranchID'];	$conn = _connectodb();	$response['data'] = getAssets($conn,$BranchID);	$response["error"] = false;	$response["message"] = "Branch Assets Fetched";}else {	$response["error"] = true;	$response["message"] = "Missing User Fields";}echo json_encode($response);?>